"""Durable JSON-lines log for receive / assemble / delivery commit points.

Every state-changing decision is appended (and fsynced) before it is
reported to the caller, so a crash can lose at most the unacknowledged
frames.  Recovery replays the log deterministically.
"""

from __future__ import annotations

import json
import os


class DurableLog:
    def __init__(self, path=None):
        self.path = path
        self.records = []
        self._fh = None
        if path is not None:
            self._fh = open(path, "a", encoding="utf-8")

    def record(self, kind, **fields):
        rec = {"kind": kind}
        rec.update(fields)
        self.records.append(rec)
        if self._fh is not None:
            self._fh.write(json.dumps(rec, sort_keys=True) + "\n")
            self._fh.flush()
            os.fsync(self._fh.fileno())
        return rec

    def close(self):
        if self._fh is not None:
            self._fh.close()
            self._fh = None

    @staticmethod
    def replay(path):
        events = []
        if path is None or not os.path.exists(path):
            return events
        with open(path, "r", encoding="utf-8") as fh:
            for line in fh:
                line = line.strip()
                if line:
                    events.append(json.loads(line))
        return events

"""Per-(stream, epoch) reassembly buffer with windowed flow control."""

from __future__ import annotations

from . import seqnum

ACCEPTED = "accepted"
DUPLICATE = "duplicate"
OLD = "old"                # unambiguously in the past
AMBIGUOUS = "ambiguous"    # outside the valid comparison window
BUSY = "busy"              # window full: deterministic backpressure
CONFLICT = "conflict"      # same seq, different content: atomically rejected
CLOSED = "closed"          # stream already closed
INVALID = "invalid"        # malformed frame


class AcceptResult:
    def __init__(self, status, **detail):
        self.status = status
        self.detail = detail

    def to_dict(self):
        out = {"status": self.status}
        out.update(self.detail)
        return out

    def __repr__(self):
        return f"AcceptResult({self.to_dict()!r})"


class Assembly:
    """Fragments of one message.

    The first fragment pins the content hash; any later fragment
    disagreeing with it is a conflict and mutates nothing.
    """

    __slots__ = ("frags_total", "hash", "close", "parts", "complete")

    def __init__(self, frags_total, hash_, close):
        self.frags_total = frags_total
        self.hash = hash_
        self.close = close
        self.parts = {}
        self.complete = False

    def add(self, frame):
        """Returns 'ok', 'duplicate' or 'conflict'. Never mutates on conflict."""
        if (
            frame.hash != self.hash
            or frame.frags != self.frags_total
            or frame.close != self.close
            or not (0 <= frame.frag < self.frags_total)
        ):
            return "conflict"
        if frame.frag in self.parts:
            if self.parts[frame.frag] != frame.payload:
                return "conflict"
            return "duplicate"
        self.parts[frame.frag] = frame.payload
        if len(self.parts) == self.frags_total:
            self.complete = True
        return "ok"

    def content(self):
        return "".join(self.parts[i] for i in range(self.frags_total))


class ReassemblyBuffer:
    def __init__(self, stream, epoch, mod, window):
        seqnum.check_window_params(mod, window)
        self.stream = stream
        self.epoch = epoch
        self.mod = mod
        self.window = window
        self.next_seq = 0            # next sequence number to deliver (cyclic)
        self.delivered_count = 0     # absolute delivery cursor inside the epoch
        self.slots = {}              # seq -> Assembly (window occupancy)
        self.received_abs = set()    # absolute indices of fully received messages
        self.delivered_hashes = {}   # seq -> hash of recently delivered messages
        self.closed = False
        self.evidence = []           # retained conflict evidence

    def _classify(self, seq):
        return seqnum.classify(seq, self.next_seq, self.mod, self.window)

    def _abs_index(self, seq):
        return self.delivered_count + seqnum.fwd_dist(self.next_seq, seq, self.mod)

    def accept(self, frame):
        if frame.stream != self.stream or frame.epoch != self.epoch:
            return AcceptResult(INVALID, reason="wrong stream/epoch")
        if frame.frags < 1 or not (0 <= frame.frag < frame.frags):
            return AcceptResult(INVALID, reason="bad fragment coordinates")
        if self.closed:
            return AcceptResult(CLOSED, reason="stream closed", seq=frame.seq)

        cls = self._classify(frame.seq)
        if cls == seqnum.PAST:
            kept = self.delivered_hashes.get(frame.seq)
            if kept is not None and kept != frame.hash:
                ev = self._evidence(frame, kept_hash=kept, kept_payload=None)
                return AcceptResult(CONFLICT, **ev)
            return AcceptResult(OLD, seq=frame.seq, next_seq=self.next_seq)
        if cls == seqnum.AMBIGUOUS:
            return AcceptResult(AMBIGUOUS, seq=frame.seq, next_seq=self.next_seq)

        asm = self.slots.get(frame.seq)
        if asm is None:
            if len(self.slots) >= self.window:
                # Deterministic backpressure: the decision depends only on
                # current state, and no acknowledged data is ever evicted.
                return AcceptResult(
                    BUSY,
                    seq=frame.seq,
                    window=self.window,
                    buffered=sorted(self.slots),
                )
            asm = Assembly(frame.frags, frame.hash, frame.close)
            verdict = asm.add(frame)
            if verdict == "conflict":  # unreachable after validation, be safe
                return AcceptResult(INVALID, reason="inconsistent frame")
            self.slots[frame.seq] = asm
            if asm.complete:
                self.received_abs.add(self._abs_index(frame.seq))
            return AcceptResult(ACCEPTED, seq=frame.seq, assembled=asm.complete)

        verdict = asm.add(frame)
        if verdict == "conflict":
            ev = self._evidence(
                frame, kept_hash=asm.hash, kept_payload=asm.parts.get(frame.frag)
            )
            return AcceptResult(CONFLICT, **ev)
        if verdict == "duplicate":
            return AcceptResult(DUPLICATE, seq=frame.seq)
        if asm.complete:
            self.received_abs.add(self._abs_index(frame.seq))
        return AcceptResult(ACCEPTED, seq=frame.seq, assembled=asm.complete)

    def _evidence(self, frame, kept_hash, kept_payload):
        ev = {
            "stream": self.stream,
            "epoch": self.epoch,
            "seq": frame.seq,
            "frag": frame.frag,
            "kept_hash": kept_hash,
            "rejected_hash": frame.hash,
            "kept_payload": kept_payload,
            "rejected_payload": frame.payload,
        }
        self.evidence.append(ev)
        return ev

    def poll_ready(self):
        """Pop contiguous complete messages starting at next_seq."""
        out = []
        while True:
            asm = self.slots.get(self.next_seq)
            if asm is None or not asm.complete:
                break
            del self.slots[self.next_seq]
            out.append((self.next_seq, asm.content(), asm.hash, asm.close))
            self._remember_delivered(self.next_seq, asm.hash)
            self.next_seq = (self.next_seq + 1) % self.mod
            self.delivered_count += 1
            if asm.close:
                self.closed = True
                break
        return out

    def _remember_delivered(self, seq, hash_):
        self.delivered_hashes[seq] = hash_
        keep = set()
        for s in self.delivered_hashes:
            d = (s - self.next_seq) % self.mod
            if d >= self.mod - self.window:
                keep.add(s)
        self.delivered_hashes = {
            s: h for s, h in self.delivered_hashes.items() if s in keep
        }

    def acks(self):
        """Selective ack ranges and gap retransmit requests.

        Ranges and gaps are offsets relative to ``next_seq``; only offsets
        inside the valid comparison window are reported, so no cyclic
        number is ever compared outside its valid window.
        """
        offsets = sorted(
            a - self.delivered_count
            for a in self.received_abs
            if -self.window <= a - self.delivered_count < self.window
        )
        ranges = []
        for off in offsets:
            if ranges and off == ranges[-1][1] + 1:
                ranges[-1][1] = off
            else:
                ranges.append([off, off])
        gaps = []
        if offsets:
            have = set(offsets)
            for off in range(0, offsets[-1] + 1):
                if off in have:
                    continue
                if gaps and off == gaps[-1][1] + 1:
                    gaps[-1][1] = off
                else:
                    gaps.append([off, off])
        retransmit = [
            (self.next_seq + off) % self.mod
            for start, end in gaps
            for off in range(start, end + 1)
        ]
        return {
            "stream": self.stream,
            "epoch": self.epoch,
            "next_seq": self.next_seq,
            "delivered": self.delivered_count,
            "closed": self.closed,
            "ack_ranges": ranges,
            "gap_ranges": gaps,
            "retransmit": retransmit,
        }

"""Independent unbounded reference buffer model.

Used only to cross-check the real engine: it has no receive window, no
backpressure and no persistence.  It implements the same externally
visible contract (first content hash wins per message, conflicting
content is rejected, delivery is contiguous from sequence 0 and stops
at a close message) with a deliberately separate, simpler
implementation.
"""

from __future__ import annotations

from .frames import Frame


class ReferenceModel:
    def __init__(self, mod):
        self.mod = mod
        self.messages = {}
        self.conflicts = []

    def offer(self, frame):
        if isinstance(frame, dict):
            frame = Frame.from_dict(frame)
        key = (frame.stream, frame.epoch, frame.seq)
        msg = self.messages.get(key)
        if msg is None:
            if frame.frags < 1 or not (0 <= frame.frag < frame.frags):
                return
            msg = {"hash": frame.hash, "frags": frame.frags,
                   "close": frame.close, "parts": {}}
            self.messages[key] = msg
        if (
            frame.hash != msg["hash"]
            or frame.frags != msg["frags"]
            or frame.close != msg["close"]
            or not (0 <= frame.frag < msg["frags"])
            or (frame.frag in msg["parts"]
                and msg["parts"][frame.frag] != frame.payload)
        ):
            self.conflicts.append((key, frame.hash))
            return
        msg["parts"][frame.frag] = frame.payload

    def delivered(self):
        """Delivered output per (stream, epoch), in sequence order."""
        by_stream = {}
        for (stream, epoch, seq), msg in self.messages.items():
            by_stream.setdefault((stream, epoch), {})[seq] = msg
        out = {}
        for key in sorted(by_stream):
            seqs = by_stream[key]
            records = []
            next_seq = 0
            for _ in range(self.mod):
                msg = seqs.get(next_seq)
                if msg is None or len(msg["parts"]) < msg["frags"]:
                    break
                content = "".join(msg["parts"][i] for i in range(msg["frags"]))
                records.append({
                    "stream": key[0],
                    "epoch": key[1],
                    "seq": next_seq,
                    "content": content,
                    "hash": msg["hash"],
                    "close": msg["close"],
                })
                next_seq = (next_seq + 1) % self.mod
                if msg["close"]:
                    break
            out[key] = records
        return out

"""Virtual network: deterministic schedule runner and cross-checker.

A schedule is a list of frames offered in order.  Frames answered with
deterministic backpressure (busy) or classified ambiguous (too far
ahead of the window) are parked and retried whenever the engine state
changes, modelling a sender that retransmits until acknowledged.

``compare`` runs the same schedule through the engine and through the
independent unbounded reference model and reports any divergence in
delivered output.  ``minimize_failing`` shrinks a failing schedule to
a minimal replayable one.
"""

from __future__ import annotations

from .engine import DeliveryEngine
from .frames import Frame
from .log import DurableLog
from .receiver import AMBIGUOUS, BUSY
from .refmodel import ReferenceModel

RETRYABLE = (BUSY, AMBIGUOUS)


def run_schedule(schedule, mod, window, prefix=()):
    """Run a schedule through the engine. Returns (outputs, engine, parked)."""
    engine = DeliveryEngine(mod=mod, window=window, log=DurableLog(None))
    outputs = []
    for frame in prefix:
        engine.offer(_as_frame(frame))
    outputs.extend(engine.poll())

    parked = []

    def pump():
        progressed = True
        while progressed:
            progressed = False
            new = engine.poll()
            if new:
                outputs.extend(new)
                progressed = True
            if parked:
                still = []
                for f in parked:
                    status = engine.offer(f)["status"]
                    if status in RETRYABLE:
                        still.append(f)
                    else:
                        progressed = True
                if len(still) != len(parked):
                    parked[:] = still

    for frame in schedule:
        frame = _as_frame(frame)
        status = engine.offer(frame)["status"]
        if status in RETRYABLE:
            parked.append(frame)
        pump()
    for _ in range(2 * len(parked) + 4):
        if not parked:
            break
        before = (len(parked), len(outputs))
        pump()
        if (len(parked), len(outputs)) == before:
            break
    return outputs, engine, list(parked)


def compare(schedule, mod, window, prefix=()):
    """Cross-check engine output against the reference model."""
    outputs, _engine, _parked = run_schedule(schedule, mod, window, prefix)
    ref = ReferenceModel(mod)
    for frame in list(prefix) + list(schedule):
        ref.offer(_as_frame(frame))
    ref_delivered = ref.delivered()
    eng_grouped = {}
    for rec in outputs:
        eng_grouped.setdefault((rec["stream"], rec["epoch"]), []).append(
            {k: rec[k] for k in ("seq", "content", "hash", "close")}
        )
    mismatches = []
    keys = sorted(set(ref_delivered) | set(eng_grouped))
    for key in keys:
        ref_recs = [
            {k: r[k] for k in ("seq", "content", "hash", "close")}
            for r in ref_delivered.get(key, [])
        ]
        eng_recs = eng_grouped.get(key, [])
        if ref_recs != eng_recs:
            mismatches.append({
                "stream": key[0],
                "epoch": key[1],
                "engine": eng_recs,
                "reference": ref_recs,
            })
    return mismatches


def minimize_failing(schedule, is_failing):
    """Greedy 1-minimality: remove frames while the schedule still fails."""
    sched = list(schedule)
    changed = True
    while changed:
        changed = False
        for i in range(len(sched)):
            candidate = sched[:i] + sched[i + 1:]
            if candidate and is_failing(candidate):
                sched = candidate
                changed = True
                break
    return sched


def replay_file(path, mod, window):
    """Replay a recorded JSON schedule; returns the delivered outputs."""
    import json

    with open(path, "r", encoding="utf-8") as fh:
        doc = json.load(fh)
    prefix = [Frame.from_dict(d) for d in doc.get("prefix", [])]
    schedule = [Frame.from_dict(d) for d in doc["schedule"]]
    outputs, _engine, parked = run_schedule(schedule, mod, window, prefix)
    return {"outputs": outputs, "parked": [f.to_dict() for f in parked]}


def _as_frame(frame):
    return Frame.from_dict(frame) if isinstance(frame, dict) else frame

"""JSON-lines CLI.

Usage: python3.11 -m msdeliv.cli < commands.jsonl

One JSON command per line on stdin, one JSON event per line on stdout.

Commands:
  {"op":"new","mod":16,"window":4,"log":"path.jsonl"}   start a session
  {"op":"send","frame":{...}}                           offer one frame
  {"op":"poll"}                                         commit deliveries
  {"op":"acks","stream":"s","epoch":0}                  selective acks
  {"op":"state"}                                        engine state
  {"op":"crash"}                                        drop memory, keep log
  {"op":"recover"}                                      rebuild from log
  {"op":"replay","schedule":[...],"prefix":[...]}       run via virtual net
  {"op":"verify","schedule":[...],"prefix":[...]}       cross-check vs model
"""

from __future__ import annotations

import json
import sys

from . import vnet
from .engine import DeliveryEngine
from .frames import Frame
from .log import DurableLog


class Session:
    def __init__(self):
        self.engine = None
        self.log_path = None
        self.mod = None
        self.window = None

    def handle(self, cmd):
        op = cmd.get("op")
        handler = getattr(self, f"op_{op}", None)
        if handler is None:
            return {"event": "error", "error": f"unknown op: {op}"}
        try:
            return handler(cmd)
        except Exception as exc:  # keep the CLI total: report, don't crash
            return {"event": "error", "error": f"{type(exc).__name__}: {exc}"}

    def op_new(self, cmd):
        self.mod = int(cmd.get("mod", 1 << 16))
        self.window = int(cmd.get("window", 8))
        self.log_path = cmd.get("log")
        if self.log_path:
            open(self.log_path, "w").close()  # fresh session truncates the log
        self.engine = DeliveryEngine(mod=self.mod, window=self.window,
                                     log=DurableLog(self.log_path))
        return {"event": "ready", "mod": self.mod, "window": self.window}

    def op_send(self, cmd):
        result = self.engine.offer(Frame.from_dict(cmd["frame"]))
        result["event"] = "accept"
        return result

    def op_poll(self, cmd):
        return {"event": "delivered", "outputs": self.engine.poll()}

    def op_acks(self, cmd):
        return {"event": "acks",
                "acks": self.engine.acks(cmd["stream"], int(cmd["epoch"]))}

    def op_state(self, cmd):
        return {"event": "state", "state": self.engine.state()}

    def op_crash(self, cmd):
        if self.engine is not None:
            self.engine.log.close()
        self.engine = None
        return {"event": "crashed"}

    def op_recover(self, cmd):
        path = cmd.get("log", self.log_path)
        self.engine = DeliveryEngine.recover(path)
        self.mod, self.window = self.engine.mod, self.engine.window
        return {"event": "recovered", "cursor": self.engine.cursor,
                "state": self.engine.state()}

    def op_replay(self, cmd):
        mod = int(cmd.get("mod", self.mod or (1 << 16)))
        window = int(cmd.get("window", self.window or 8))
        prefix = [Frame.from_dict(d) for d in cmd.get("prefix", [])]
        schedule = [Frame.from_dict(d) for d in cmd["schedule"]]
        outputs, _engine, parked = vnet.run_schedule(schedule, mod, window,
                                                     prefix)
        return {"event": "outputs", "outputs": outputs,
                "parked": [f.to_dict() for f in parked]}

    def op_verify(self, cmd):
        mod = int(cmd.get("mod", self.mod or (1 << 16)))
        window = int(cmd.get("window", self.window or 8))
        prefix = [Frame.from_dict(d) for d in cmd.get("prefix", [])]
        schedule = [Frame.from_dict(d) for d in cmd["schedule"]]
        mismatches = vnet.compare(schedule, mod, window, prefix)
        if not mismatches:
            return {"event": "ok"}
        minimal = vnet.minimize_failing(
            schedule,
            lambda s: bool(vnet.compare(s, mod, window, prefix)),
        )
        return {
            "event": "mismatch",
            "mismatches": mismatches,
            "minimal_schedule": [f.to_dict() for f in minimal],
            "prefix": [f.to_dict() for f in prefix],
            "mod": mod,
            "window": window,
        }


def main(argv=None):
    session = Session()
    out = sys.stdout
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        try:
            cmd = json.loads(line)
        except json.JSONDecodeError as exc:
            out.write(json.dumps({"event": "error", "error": str(exc)}) + "\n")
            out.flush()
            continue
        out.write(json.dumps(session.handle(cmd), sort_keys=True) + "\n")
        out.flush()
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

